#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    errno = 0;
    long n = strtol(argv[1], &end1, 10);
    long m = strtol(argv[2], &end2, 10);
    // check conversion succeeded and consumed whole string
    if (errno != 0 || *end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (m < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (m > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    const double C = 1.0; // constant used in the original binary
    double sum = 0.0;
    if (n == 2) {
        // sum of 1/(i*i) for i = 1..m, multiplied by C
        for (long i = 1; i <= m; ++i) {
            sum += C / ((double)i * (double)i);
        }
    } else if (n == 3) {
        // sum of 1/k! for k = 0..m, multiplied by C
        double term = 1.0; // 1/0!
        sum = C * term; // start with k=0 term
        for (long k = 1; k <= m; ++k) {
            term /= (double)k; // term = 1/k!
            sum += C * term;
        }
    } else {
        puts("BAD_MODE");
        return 0;
    }
    printf("%.6f\n", sum);
    return 0;
}
}
